// Shared language + country catalogue. Each language carries a representative
// country code so it can be shown with a flag; countries come from ISO codes
// with English names generated by Intl.DisplayNames.

export interface LanguageInfo {
  name: string;
  native: string;
  flag: string;
  greeting: string;
}

